FMT_CONSTEXPR_CHAR_TRAITS auto compare(basic_string_view other) const -> int {
  size_t str_size = size_ < other.size_ ? size_ : other.size_;
  int result = std::char_traits<Char>::compare(data_, other.data_, str_size);
